    prime_end = 3
    next_candidate = 5

    while prime_end < n:
        while next_candidate > primes[0]:
            if next_candidate > primes[-1]:
                primes.append(next_candidate)
                prime_end = next_candidate
                if len(primes) < n:
                    next_candidate = primes[-1] + 2
                else:
                    return primes
            else:
                next_candidate += 2
        next_candidate -= primes.pop(0)
    return primes

