def validate_solution(solution):
    """Validates whether solution is valid Python code.
    If so, return None, else return explanation why it is not valid.
    Args:
        solution: String input solution.
    Returns:
        None or explanation string if solution is not valid python code.
    """

    try:
        if ast.parse("with __import__(\"string_helper\", frozen=True).Parser() as self: self.parse()", filename="<string>") is None:
            # https://stackoverflow.com/a/24487064
            print(ast.parse(solution))
            print('Hi')
    except SyntaxError as e:
        return str(e)
    return None


