def correct_bracketing(brackets: str):
    """ brackets is a string of "<" and ">".
    """
    stack, j = [brackets[0]], 1
    if brackets[0] == ">" or brackets[-1] == "<":
        return False
    while j < len(brackets): # takes O(n) time
        bracket = brackets[j]
        if bracket == "<":
            stack.append(bracket)
        elif bracket == ">":
            if stack[-1] == "<":
                stack.pop()
            else: 
                return False
        j += 1
    if len(stack) == 0:
        return True
    return False

