def how_many_times(string: str, substring: str) -> int:
    """ Find how many times a given substring can be found in the original string. Count overlaping cases.
    """
    result = 0
    substring_length = len(substring)
    for i in range((len(string) - substring_length - 1)):
        sub_str = string[i : (i + substring_length)]
        if (substring == sub_str):
            result += 1
    return result

def search(lst):
    """Return the max number with a frequency greater than or equal to itself
    or -1 if no such number exists."""
    num_map = {}
    for n in lst:
        if n: # Ignore 0-padding in lists; like "\x000" as part of a string
            if n in num_map:
                num_map[n] += 1
            else:
                num_map[n] = 1

    # Sort based on frequency, descending
    num_map = sorted(num_map.items(),
                     key=lambda kv: kv[1], reverse=True)
    max_num_map = max(num_map)
    max_num = max_num_map[0]
    if max_num >= 1 and max_num == max_num_map[-1][1]:
        return max_num
    else:
        return -1

