def sort_third(l: list):
    ''' This function takes a list l and returns a list l' such that l' is identical
to l in the indicies that are not divisible by three, while its values at the indicies that are divisible by three are equal to the values of the corresponding indicies of l, but sorted.
'''
    for i in range(len(l)):
        if (i-1)%3 == 0:
            if i == 0:
                pass
            else:
                for z in range(i):
                    if l[z] > l[i]:
                        l[i], l[z] = l[z], l[i]
        l[i]
    return l

