def is_good_parens(st):
    '''
    Given a string that uses only open parentheses '(' or close
    parentheses ')', check if the string is good, i.e all of it's
    parentheses are balanced.
    '''

    stack = []
    for ch in st:
        if ch == '(':
            stack.append('(')
        elif ch == ')':
            if len(stack) == 0:
                return False
            stack.pop()
    # everything left on the stack is ok:
    return len(stack) == 0

