def smallest_change(arr):
    count = [1] * 100
    for a, b in zip(arr, arr[1:]):
        if a % 2 == 0 and b % 2 == 0:
            count[int(a / 2)] += 1
            count[int(b / 2)] -= 1
        elif a % 2 == 1 and b % 2 == 1:
            count[a - 1] += 1
            count[b - 1] -= 1
        elif a % 2 == 0 and b % 2 == 1:
            count[a / 2] -= 1
        index = min(range(len(count)), key=count.__getitem__)
        if index <= 1:
            break
        arr[arr.index(index * 2) + 1] = index * 2
        print("*** Changed arr to:", arr)
    return sum(count)

