from HTMLParser import HTMLParser


class Parser(HTMLParser):
    in_code_block = False
    answer = []
    # current_tag = None
    current_attrs = None
    is_python_solution = True

    def handle_starttag(self, tag, attrs):
        if tag == 'pre':
            for attr in attrs:
                if attr[0] == 'class' and attr[1] == 'solution':
                    self.in_code_block = True
                    self.is_python_solution = True
        if self.in_code_block:
            if tag == 'code':
                self.in_code_block = False
            """
            if self.in_code_block and tag == 'p':
                self.is_python_solution = False
            """

    def handle_endtag(self, tag):
        if tag == 'pre':
            if self.is_python_solution:
                self.answer.append("</code>")

    def handle_data(self, data):
        if self.in_code_block:
            self.answer.append(data)


def render(source):
    py_to_html = "<pre>  <code class='solution'> "

    for line in source.split("</code>"):
        py_to_html += line + "</code> </pre> "
        parser = Parser()
        parser.feed(py_to_html)

        result = "".join(parser.answer)
        # Render markdown

        return "- %s\n<code>\n        %s\n</code>\n" % (result, result)


