def minSubArraySum(nums):
    # . is a reserved character in py
    if nums == ['.']:
        return '.'
    # if it is just one number,
    # no subarray has to contribute to its sum
    if len(nums) == 1:
        return int(nums[0])
    # (0, i) will go to left and (i, n-1) to the right
    # subarray with lowest sum will be min(subarray with leftmost starting
    # point, subarray with leftmost ending point)
    # loops here will drill down to all valid subarrays
    # break up the array into different sub-arrays
    start = 0
    # end will be every single number position
    for end in range(len(nums) - 1):
        # what (i, n-1) is then what (i, j) becomes
        for j in range(start + 1, end + 1):
            # recursive call is to (0, j)
            if minSubArraySum(nums[:start] + nums[start:j] + nums[j + 1 :]) < int(nums[end]):
