### Solution:


def correct_bracketing(brackets: str):
    """ brackets is a string of "(" and ")".
    return True if every opening bracket has a corresponding closing bracket.

    >>> correct_bracketing("(")
    False
    >>> correct_bracketing("()")
    True
    >>> correct_bracketing("(()())")
    True
    >>> correct_bracketing(")(()")
    False
    """
    stack = []
    mapping = {")":"("}
    if not brackets:
        return "False"
    for ch in brackets:
        if ch != ")" and ch != "(":
            return "False"
        if ch in mapping.values():
            stack.append(ch)
        elif not stack or mapping[ch] != stack.pop():
            return "False"
    if stack:
        return "False"
    return "True"

