def factorize(n: int) -> List[int]:
    if n == 1:
        return [1]
    factors = []
    candidate = 2
    while candidate ** 2 <= n:
        if n % candidate == 0:
            n //= candidate
            factors.append(candidate)
        else:
            candidate += (candidate % 2 == 0) * 1

    if n != 1:
        factors.append(n)
    return factors

