class Solution:
    def search(self, lst):
        """
        >>> search([4, 1, 2, 2, 3, 1])
        2
        >>> search([1, 2, 2, 3, 3, 3, 4, 4, 4])
        3
        >>> search([5, 5, 4, 4, 4])
        -1
        """
        # put all the duplicate items together, so that picking an item will not need to traverse the list.
        d = {}
        for item in lst:
            if d.get(item):
                d[item] += 1
            else:
                d[item] = 1
        # sort the d now, so that we can binary search on it
        del d['']
        d = {int(k): v for k, v in sorted(d.items(), key=lambda d: -d[0])}
        for key, _ in d.items():
            #if this key is in val than return the key
            if lst.count(key) >= key:
                return key
        return -1

