def make_a_pile(n):
    if n <= 0:
        raise ValueError("n must be positive")
    s = [n]
    while n != 1:
        n -= 1
        if not n % 2:
            next_level = n + 1
        else:
            next_level = n + 2
        s.append(next_level)
        n = next_level
    return s

