    while alive > 0:
        # from the list sentinel which was the first,
        # choose a not hostile survivor
        arr.remove(min(arr[1::2], key=lambda element: element))
        # from the list remaining, choose alive survivors
        arr.remove(min(list(filter(lambda element: element > 0, arr[1::2])), key=lambda element: element))
        # each step kills a not hostile and alive
        alive -= 1
    return(arr[0])


