def zip_third(l1, l2, l3):
    """
    Zip the lists l1, l2, l3 together into list l.

    >>> zip_third([3, 4, 7], [12, 16], [1, 16])
    [4, 16, 16]
    >>> zip_third([3, 4, 8], [12, 16], [10, 16])
    [16, 16, 16]
    """
    ans = []
    for i in range(min(len(l1), len(l2), len(l3))):
      if i % 3: ans.append(l1[i])
      else: ans.append(min(l2[i], l3[i]))
    return ans

def correct_bracketing(brackets):
    open_count, close_count = 0, 0
    for bracket in brackets:  
        if bracket == "<":
            open_count += 1
        elif bracket == ">":
            close_count += 1
            if open_count <= close_count:
                return False
    return open_count == close_count

