def maxSubArray(nums):
    """
    Find the contiguous sub-array with the largest sum.
    return sums (or None if empty list provided)
    """
    if not nums:
        return None
    sums = nums[:]  # list of cumulative sums; initialize to input
    for i in range(1, len(sums)):
        sums[i] += sums[i - 1]
    result = max(sums)

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            subarr = nums[i:j+1]
            if sum(subarr) == result:
                return subarr
    return [result]


