def separate_paren_groups(paren_string: str) -> List[str]:
    assert paren_string != ''
    stk = []
    l, r = 0, 0
    parens = '()'

    for c in paren_string:
        if c not in parens:
            continue
        if c == parens[0]:  # (     Left Paren
            stk.append(c)
            l = max(l, len(stk))
        elif c == parens[1] and len(stk) > 0:  #  )     Right Paren, only use it if the stk is empty
            o = stk.pop()
            if len(stk) == 0:
                r = max(r, l)
            elif stk[-1] == parens[0]:    #  )     Right Paren, and if it's nested in a Left Paren
                r = max(l)
        elif len(c) > 0:
            return []
    elif r != 0:
        stk = []
        r = max(r)
    return [
        '(' * l + ')' * r + ''.join(c for c in stk)
        for l in range(1, r + 1)
        if all(paren_string[ind] == '(' for ind in range(l - 1, l + r))
    ]
