def separate_paren_groups(paren_string: str) -> List[str]:
    """
    >>> separate_paren_groups('( () (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    copied_paren_string = paren_string.replace(" ", "")
    parens_stack = ""
    result = []
    counter = 0

    while counter < (len(copied_paren_string)) - 1:
        if copied_paren_string[counter] == "(":
            parens_stack += "("

        elif copied_paren_string[counter] == ")":
            parens_stack += ")"

        if parens_stack == "()":
            result.append(parens_stack)
            parens_stack = ""
            break
        counter += 1

    counter += 1

    while counter < (len(copied_paren_string)) - 1:
        if copied_paren_string[counter] == "(":
            parens_stack += "("

        elif copied_paren_string[counter] == ")":
            parens_stack += ")"

        for paren in parens_stack:
            if paren == "(":
                if parens_stack == "()":
                    result.append(parens_stack)
                    parens_stack = ""
                    break
            counter += 1

    return result

