def check_rotation ( a, b ):
    N = min ( len ( a ), len ( b ) ) - 1
    if not ( len ( a ) == len ( b ) ) or N == - 1:
        return False
    else:
        if a [ : N ] + a [ N : ] == b [ : N ] + b [ N : ]:
            return True
        elif a [ N ] + a [ : N ] + a [ N : ] == b [ : N ] + b [ N : ]:
            return True
    return False

