def find_closest_elements(numbers):
    """From a supplied list of numbers (of length at least two) select and
    return two that are the closest to each other and return them in order
    (smaller number, larger number).
    """
    min_dist, min_pair = 1.0, (1.0, 1.0)
    for number1 in numbers:
        for number2 in numbers:
            dist = abs(number1 - number2)
            if dist == 0:
                continue
            if dist < min_dist:
                sorted_pair = (
                    min(number1, number2),
                    max(number1, number2),
                )
                min_pair = sorted_pair
                min_dist = dist
    return min_pair

def find_closest_elements(numbers):
    min_diff = numbers[1] -numbers[0]
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[j]- numbers[i]) < min_diff:
                min_diff = abs(numbers[j] - numbers[i])
                res = numbers[i], numbers[j]
    return res[0], res[1]

