def fib4(n):
    if n <= 1:
        return 0
    elif n <= 3:
        return 2
    i, a, b, c = 4, 1, 1, 2
    while i <= n:
        total = a + b + c
        a = b
        b = c
        c = total
        i += 1
    return total - c

