def minPath(grid, k):
    p = [[0 for i in range(len(grid[0]))] for j in range(len(grid))]
    DIRECTIONS = [(0,1), (1,0), (-1,0), (0,-1)]
    def solution(i, j, k):
        if k == 0:
            return p[i][j], 0 #, -1
        p[i][j] += 1
        result, slot = float("INF"), 0
        for x,y in [(0,-1), (0,1),(-1,0),(1,0)]:
            xi = i+x
            yj = j+y
            if (0<=xi<len(grid) and 0<=yj<len(grid[0])):
                value, slot = solution(xi, yj, k-1)
                if value < result or (value==result and slot<=slot+1):
                    result, slot = value, slot+1
        p[i][j] -= 1
        if k==1:
            return result, slot
        return min(result, k-slot)
    return solution(0, 0, k-1)

