    """Return the tuple (e, o)."""
    total_even = 1
    total_odd = 1
    m = 2
    while m*m <= n:
        if m % 4 == 1:
            total_even += (n//m) + (n//m-1)
        elif m % 4 == 3:
            total_odd += (n//m) + (n//m-1)
