def fib4(n: int):
    fib_pre_2 = 1
    fib_pre_1 = 0
    fib_n = 0

    if n in [0, 1]:
        fib_n = 0
    elif n == 2:
        fib_n = 2
    elif n == 3 :
        fib_n = 2
    else:
        i = 3
        while i <= n:
            tmp = fib_pre_2 + fib_pre_1 + fib_n

            fib_pre_2 = fib_pre_1
            fib_pre_1 = fib_n
            fib_n = tmp

            i += 1

        fib_n = tmp

    return fib_n

