def random_location(text):
    """Locate a random span in text that contains either one or the other word"""
    candidates = []
    for m in re.finditer(r"[^ ]*(?:\bPARAM\b|\bRESPONSE\b) ?.*?[^ ]*\b(?:FRAME TYPE\b)?[^ ]*", text):
        span = m.span()
