def max_fill(grid, bucket_capacity):
  n_rows = len(grid)
  n_cols = len(grid[0])
  water_level = 0
  n_draws = 0

  while bucket_capacity > 0:
    found_unit = False
    for i in range(n_rows):
      if found_unit:
        break
      for j in range(n_cols):
        if grid[i][j] == 1:
          found_unit = True
          break
    if not found_unit:
      return n_draws
    water_level += 1
    for i in range(n_rows):
      bucket_capacity = max(bucket_capacity, (n_rows - i) * water_level)
      while (bucket_capacity > 0) and (j < n_cols):
        bucket_capacity -= 1
        if grid[i][j] == 1:
          grid[i][j] = 0
        j += 1
    n_draws += 1
  return n_draws
