### Solution:
def vowels_count(wordstring):
    vowels = ["a", "e", "i", "o", "u", "y"]
    count = 0
    for char in list(wordstring.lower()):
        if char in vowels:
            count += 1
    if "y" == list(wordstring.lower())[-1]:
        count += 1
    return count

