def my_round(number):
    if number % 5 > 2:
        return number // 5 + 1
    elif number % 5 > 1:
        return number // 5
    else:
        return number // 5

def rounded_avg(n, m):

    if n>m:
        return -1

    result=0
    for num in range(n+1, m+1):
        for num1 in range(2):
