def pluck(arr):
  if not arr:
    return []

  min = low = high = 0

  while low <= high:
    mid = int(low + (high - low)/2)
    if not arr[mid] % 2 == 0:
      high += 1
    elif mid == len(arr) - 1:
      return arr[mid]
    elif arr[mid] < arr[mid + 1]:
      if not min or arr[mid] <= min:
        min = arr[mid]
        low = mid + 1
      else:
        high -= 1
    else:
      return [arr[mid], mid]
  return [min, low]

